import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    board = data[2:2 + r]
    m = int(data[2 + r])
    words = data[3 + r:3 + r + m]
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node['$'] = w
    found = []
    seen = [[False] * c for _ in range(r)]

    def dfs(i, j, parent):
        ch = board[i][j]
        node = parent[ch]
        if '$' in node:
            found.append(node.pop('$'))
        seen[i][j] = True
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c and not seen[ni][nj] and board[ni][nj] in node:
                dfs(ni, nj, node)
        seen[i][j] = False
        if not node:
            del parent[ch]

    for i in range(r):
        for j in range(c):
            if board[i][j] in root:
                dfs(i, j, root)
    found.sort()
    print(len(found))
    for w in found:
        print(w)

