words = data[3 + r:3 + r + m]

def exists(word):
    used = set()
    def go(i, j, k):
        if board[i][j] != word[k]:
            return False
        if k == len(word) - 1:
            return True
        used.add((i, j))
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c and (ni, nj) not in used:
                if go(ni, nj, k + 1):
                    used.discard((i, j))
                    return True
        used.discard((i, j))
        return False
    for i in range(r):
        for j in range(c):
            if go(i, j, 0):
                return True
    return False

res = sorted(w for w in words if exists(w))
print(len(res))
for w in res:
    print(w)

